SBOS_SetWindowProc.example:
static CGWindowProcRes window_proc(CGWindow win, const CGMessage_t *m)
{
    if (m->eventClass == CGEVT_WIN_CLOSE_REQUEST) {
        SBOS_CloseWindow(win);
        return CGPROC_HANDLED;
    }
    return CGPROC_DEFAULT;
}

SBOS_SetWindowProc(win, window_proc);

